{"task": "Count events whose path contains a standard UUID anywhere in the string", "sql": "SELECT COUNT(*) FROM events WHERE regexp_like(path, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}')"}
{"task": "List distinct paths containing a UUID segment along with their status codes", "sql": "SELECT DISTINCT path, status FROM events WHERE regexp_like(path, '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', 'i')"}
{"task": "Find error-status events whose path has a UUID to investigate failing resource-specific requests", "sql": "SELECT id, user_id, path, status FROM events WHERE status >= 500 AND regexp_like(path, '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', 'i')"}
{"task": "Tag each event path as UUID or non-UUID using a CASE expression based on regexp_like", "sql": "SELECT id, path, CASE WHEN regexp_like(path, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}') THEN 'has_uuid' ELSE 'no_uuid' END AS uuid_flag FROM events"}
{"task": "Count how many distinct user_ids made requests to UUID-containing paths", "sql": "SELECT COUNT(DISTINCT user_id) AS users_with_uuid_paths FROM events WHERE regexp_like(path, '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', 'i')"}
{"task": "Join logs and events to find log lines mentioning a UUID that also appear around requests to UUID-bearing paths on the same path string", "sql": "SELECT l.ts, l.level, l.message, e.path FROM logs l JOIN events e ON regexp_like(l.message, substring(e.path, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}')) WHERE regexp_like(e.path, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}')"}
{"task": "Compute the percentage of total requests whose path contains a UUID", "sql": "SELECT 100.0 * SUM(CASE WHEN regexp_like(path, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}') THEN 1 ELSE 0 END) / COUNT(*) AS pct_uuid_paths FROM events"}
{"task": "Find paths with a UUID immediately followed by a query string to spot resource-id-based endpoints with parameters", "sql": "SELECT path FROM events WHERE regexp_like(path, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\\?')"}
{"task": "Group UUID-containing event paths by status code to see distribution of outcomes for resource-specific calls", "sql": "SELECT status, COUNT(*) AS cnt FROM events WHERE regexp_like(path, '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', 'i') GROUP BY status ORDER BY cnt DESC"}
{"task": "Identify paths that contain multiple UUIDs, suggesting nested resource relationships", "sql": "SELECT path FROM events WHERE regexp_like(path, '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}).*([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})')"}

